def _cancel_decision_schema() -> tuple[dict[str, Any], list[str]]:
    return (
        _object_schema(
            schema_id="strixnova.cancellation-decision-input.v1",
            required=("decision", "details", "confirm_discard"),
            properties={
                "decision": {"enum": ["preserve", "transfer", "discard"]},
