def _empty_schema(schema_id: str) -> tuple[dict[str, Any], list[str]]:
    return _object_schema(schema_id=schema_id), []


def _merge_schema(schema_id: str) -> tuple[dict[str, Any], list[str]]:
    return (
        _object_schema(
