            "by_state": dict(sorted(counts.items())),
            "completed_external_receipt_count": sum(
                1
                for item in selected
                if item["state"] == "completed"
                and bool(item["external_receipts"])
            ),
            "strixnova_executes_external_activity": False,
        }

